#[cfg(test)]
mod tests {
    use super::*;

    /// 测试: build() 生成正确的头部（长度 + 包ID）
    #[test]
    fn build_correct_header() {
        let pkt = PacketBuilder::new(0x0064)
            .put_u8(0x01)
            .build();
        // 长度 = 数据(1) + 头部(4) = 5
        assert_eq!(pkt[0], 0x05);
        assert_eq!(pkt[1], 0x00);
        // 包ID = 0x0064 LE
        assert_eq!(pkt[2], 0x64);
        assert_eq!(pkt[3], 0x00);
    }

    /// 测试: put_u16 小端序
    #[test]
    fn put_u16_little_endian() {
        let pkt = PacketBuilder::new(0x0000)
            .put_u16(0x0102)
            .build();
        assert_eq!(pkt[4], 0x02);
        assert_eq!(pkt[5], 0x01);
    }

    /// 测试: put_u32 小端序
    #[test]
    fn put_u32_little_endian() {
        let pkt = PacketBuilder::new(0x0000)
            .put_u32(0x01020304)
            .build();
        assert_eq!(pkt[4], 0x04);
        assert_eq!(pkt[5], 0x03);
        assert_eq!(pkt[6], 0x02);
        assert_eq!(pkt[7], 0x01);
    }

    /// 测试: put_i32 负数
    #[test]
    fn put_i32_negative() {
        let pkt = PacketBuilder::new(0x0000)
            .put_i32(-1)
            .build();
        assert_eq!(pkt[4], 0xFF);
        assert_eq!(pkt[5], 0xFF);
        assert_eq!(pkt[6], 0xFF);
        assert_eq!(pkt[7], 0xFF);
    }

    /// 测试: put_fixed_str 短字符串用 null 填充
    #[test]
    fn put_fixed_str_pads_with_nulls() {
        let pkt = PacketBuilder::new(0x0000)
            .put_fixed_str("hi", 5)
            .build();
        assert_eq!(&pkt[4..6], b"hi");
        assert_eq!(pkt[6], 0x00);
        assert_eq!(pkt[7], 0x00);
        assert_eq!(pkt[8], 0x00);
    }

    /// 测试: put_fixed_str 长字符串被截断
    #[test]
    fn put_fixed_str_truncates_long_string() {
        let pkt = PacketBuilder::new(0x0000)
            .put_fixed_str("hello world", 5)
            .build();
        assert_eq!(&pkt[4..9], b"hello");
    }

    /// 测试: put_fixed_str 空字符串
    #[test]
    fn put_fixed_str_empty_string() {
        let pkt = PacketBuilder::new(0x0000)
            .put_fixed_str("", 3)
            .build();
        assert_eq!(&pkt[4..7], &[0x00, 0x00, 0x00]);
    }

    /// 测试: parse_string 正常解析 null 结尾字符串
    #[test]
    fn parse_string_normal() {
        let buf = b"hello\0world";
        let mut offset = 0;
        let result = parse_string(buf, &mut offset, 11);
        assert_eq!(result, Some("hello".to_string()));
        assert_eq!(offset, 6); // "hello\0" = 6字节
    }

    /// 测试: parse_string 没有 null 结尾返回 None
    #[test]
    fn parse_string_no_null_returns_none() {
        let buf = b"hello";
        let mut offset = 0;
        let result = parse_string(buf, &mut offset, 5);
        assert_eq!(result, None);
    }

    /// 测试: parse_fixed_string 解析固定长度字符串
    #[test]
    fn parse_fixed_string_trims_nulls() {
        let buf = b"hi\0\0\0";
        let mut offset = 0;
        let result = parse_fixed_string(buf, &mut offset, 5);
        assert_eq!(result, Some("hi".to_string()));
        assert_eq!(offset, 5);
    }

    /// 测试: parse_fixed_string 全 null 返回空字符串
    #[test]
    fn parse_fixed_string_all_nulls() {
        let buf = &[0x00, 0x00, 0x00];
        let mut offset = 0;
        let result = parse_fixed_string(buf, &mut offset, 3);
        assert_eq!(result, Some("".to_string()));
    }

    /// 测试: parse_fixed_string 偏移量超出缓冲区返回 None
    #[test]
    fn parse_fixed_string_offset_past_end() {
        let buf = b"hi";
        let mut offset = 5;
        let result = parse_fixed_string(buf, &mut offset, 3);
        assert_eq!(result, None);
    }

    /// 测试: 多个 put 调用正确拼接
    #[test]
    fn multiple_puts_concatenate_correctly() {
        let pkt = PacketBuilder::new(0x0064)
            .put_u8(0x01)
            .put_u16(0x0203)
            .put_u32(0x04050607)
            .build();
        // 头部4字节 + 1 + 2 + 4 = 11字节
        assert_eq!(pkt.len(), 11);
        assert_eq!(pkt[4], 0x01);
        assert_eq!(pkt[5], 0x03);
        assert_eq!(pkt[6], 0x02);
        assert_eq!(pkt[7], 0x07);
        assert_eq!(pkt[8], 0x06);
        assert_eq!(pkt[9], 0x05);
        assert_eq!(pkt[10], 0x04);
    }
}
