#[cfg(test)]
mod tests {
    use super::*;

    /// 测试: CZEnter round-trip
    #[test]
    fn cz_enter_round_trip() {
        let original = CZEnter { gc_id: 12345 };
        let pkt = original.to_packet();
        let parsed = CZEnter::from_slice(&pkt[4..]); // 跳过头部
        assert!(parsed.is_some());
        assert_eq!(parsed.unwrap().gc_id, 12345);
    }

    /// 测试: CZEnter 短数据拒绝
    #[test]
    fn cz_enter_short_data_rejected() {
        assert!(CZEnter::from_slice(&[0x01, 0x02]).is_none());
        assert!(CZEnter::from_slice(&[]).is_none());
    }

    /// 测试: CZUseSkill round-trip
    #[test]
    fn cz_use_skill_round_trip() {
        let original = CZUseSkill {
            skill_id: 10,
            target_id: 999,
            target_x: 150,
            target_y: 200,
        };
        let pkt = original.to_packet();
        let parsed = CZUseSkill::from_slice(&pkt[4..]);
        assert!(parsed.is_some());
        let s = parsed.unwrap();
        assert_eq!(s.skill_id, 10);
        assert_eq!(s.target_id, 999);
        assert_eq!(s.target_x, 150);
        assert_eq!(s.target_y, 200);
    }

    /// 测试: CZUseSkill 短数据拒绝（需要 >= 12 字节）
    #[test]
    fn cz_use_skill_short_data_rejected() {
        assert!(CZUseSkill::from_slice(&[0u8; 11]).is_none());
        assert!(CZUseSkill::from_slice(&[]).is_none());
    }

    /// 测试: CZRequestMove 短数据拒绝（需要 >= 5 字节）
    #[test]
    fn cz_request_move_short_data_rejected() {
        assert!(CZRequestMove::from_slice(&[0u8; 4]).is_none());
    }

    /// 测试: 服务器端包 from_slice 始终返回 None
    #[test]
    fn server_only_packets_return_none() {
        assert!(ZCAcceptEnter::from_slice(&[0u8; 20]).is_none());
        assert!(ZCMove::from_slice(&[0u8; 20]).is_none());
    }
}
