    /// 测试: CZTradeRequest 解析
    #[test]
    fn cz_trade_request_parse() {
        let data = 42u32.to_le_bytes();
        let pkt = CZTradeRequest::from_packet(&data);
        assert!(pkt.is_some());
        assert_eq!(pkt.unwrap().target_account_id, 42);
    }

