        assert!(CZTradeRequest::from_packet(&[0u8; 3]).is_none());
    }

    /// 测试: CZTradeAck accept=true
    #[test]
    fn cz_trade_ack_accept() {
        let pkt = CZTradeAck::from_packet(&[0x01]);
        assert!(pkt.is_some());
        assert!(pkt.unwrap().accept);
    }

    /// 测试: CZTradeAck accept=false
    #[test]
    fn cz_trade_ack_reject() {
        let pkt = CZTradeAck::from_packet(&[0x00]);
        assert!(pkt.is_some());
        assert!(!pkt.unwrap().accept);
    }

    /// 测试: ZCTradeRequest 序列化验证包ID
    #[test]
    fn zc_trade_request_packet_id() {
        let pkt = ZCTradeRequest {
            requester_id: 1,
            requester_name: "Test".to_string(),
        }.to_packet();
        assert_eq!(pkt[2], 0xE4); // 0x00E4 LE
        assert_eq!(pkt[3], 0x00);
    }

    /// 测试: ZCTradeLock 是纯头部包（4字节）
    #[test]
    fn zc_trade_lock_header_only() {
        let pkt = ZCTradeLock.to_packet();
        assert_eq!(pkt.len(), 4);
    }

    /// 测试: ZCTradeCommit 是纯头部包
    #[test]
    fn zc_trade_commit_header_only() {
        let pkt = ZCTradeCommit.to_packet();
        assert_eq!(pkt.len(), 4);
    }

    /// 测试: CZTradeAddItem 解析
    #[test]
    fn cz_trade_add_item_parse() {
        let mut data = Vec::new();
        data.extend_from_slice(&5u16.to_le_bytes()); // inventory_index
        data.extend_from_slice(&10u32.to_le_bytes()); // amount
        let pkt = CZTradeAddItem::from_packet(&data);
        assert!(pkt.is_some());
        let item = pkt.unwrap();
        assert_eq!(item.inventory_index, 5);
        assert_eq!(item.amount, 10);
    }

    /// 测试: CZTradeLock 始终返回 Some
    #[test]
    fn cz_trade_lock_always_some() {
        assert!(CZTradeLock::from_packet(&[]).is_some());
        assert!(CZTradeLock::from_packet(&[0xFF]).is_some());
