#[cfg(test)]
mod tests {
    use super::*;

    /// 测试: Row::get_i32 正常值
    #[test]
    fn row_get_i32_normal() {
        let row = Row::new(vec![Value::Int(42)]);
        assert_eq!(row.get_i32(0).unwrap(), 42);
    }

    /// 测试: Row::get_i32 越界索引
    #[test]
    fn row_get_i32_out_of_bounds() {
        let row = Row::new(vec![]);
        assert!(row.get_i32(0).is_err());
    }

    /// 测试: Row::get_i32 类型不匹配
    #[test]
    fn row_get_i32_wrong_type() {
        let row = Row::new(vec![Value::Text("hello".into())]);
        assert!(row.get_i32(0).is_err());
    }

    /// 测试: Row::get_i32 Null 值
    #[test]
    fn row_get_i32_null() {
        let row = Row::new(vec![Value::Null]);
        assert!(row.get_i32(0).is_err());
    }

    /// 测试: Row::get_string 正常
    #[test]
    fn row_get_string_normal() {
        let row = Row::new(vec![Value::Text("hello".into())]);
        assert_eq!(row.get_string(0).unwrap(), "hello");
    }

    /// 测试: Row::get_optional_string Null 返回 None
    #[test]
    fn row_get_optional_string_null() {
        let row = Row::new(vec![Value::Null]);
        assert_eq!(row.get_optional_string(0).unwrap(), None);
    }

