mod tests {
    use super::*;
    use bytes::BytesMut;

    /// 测试: 缓冲区不足4字节时应返回 Ok(None)
    #[test]
    fn decode_buffer_too_short_returns_none() {
        let mut codec = PacketCodec;
        let mut buf = BytesMut::from(&[0x00, 0x01, 0x02][..]);
        assert!(codec.decode(&mut buf).unwrap().is_none());
    }

    /// 测试: 长度字段指示数据不足时应返回 Ok(None)
    #[test]
    fn decode_incomplete_payload_returns_none() {
        let mut codec = PacketCodec;
        // 长度字段 = 8, 但只有4字节头
        let mut buf = BytesMut::from(&[0x08, 0x00, 0x64, 0x00][..]);
        assert!(codec.decode(&mut buf).unwrap().is_none());
    }

    /// 测试: 长度字段恰好为4（仅头部）的包
    #[test]
    fn decode_header_only_packet() {
        let mut codec = PacketCodec;
        let mut buf = BytesMut::from(&[0x04, 0x00, 0x64, 0x00][..]);
        let result = codec.decode(&mut buf).unwrap();
        // 取决于 Packet::from_bytes 对4字节包的处理
        assert!(result.is_some() || result.is_none()); // 验证不 panic
    }

    /// 测试: 解码后缓冲区已被消费
    #[test]
    fn decode_consumes_bytes_from_buffer() {
        let mut codec = PacketCodec;
        // 构造一个完整包 + 额外数据
        let mut buf = BytesMut::from(&[0x06, 0x00, 0x64, 0x00, 0xAA, 0xBB][..]);
        let _ = codec.decode(&mut buf).unwrap();
        // 缓冲区应该被消费了6字节
        assert!(buf.is_empty());
    }

    /// 测试: 连续多个包在同一缓冲区中
    #[test]
    fn decode_multiple_packets_in_buffer() {
        let mut codec = PacketCodec;
        // 两个包连在一起
        let data = [
            0x04, 0x00, 0x64, 0x00,  // 包1
            0x04, 0x00, 0x65, 0x00,  // 包2
        ];
        let mut buf = BytesMut::from(&data[..]);
        let _pkt1 = codec.decode(&mut buf).unwrap();
        let _pkt2 = codec.decode(&mut buf).unwrap();
        assert!(buf.is_empty());
    }

    /// 测试: encode 写入正确的字节
    #[test]
    fn encode_writes_bytes_to_destination() {
        let mut codec = PacketCodec;
        let mut dst = BytesMut::new();
        let data = vec![0x64, 0x00, 0x01, 0x02];
        codec.encode(data.clone(), &mut dst).unwrap();
        assert_eq!(&dst[..], &data[..]);
    }

    /// 测试: encode 空数据
    #[test]
    fn encode_empty_data() {
        let mut codec = PacketCodec;
        let mut dst = BytesMut::new();
        codec.encode(vec![], &mut dst).unwrap();
        assert!(dst.is_empty());
    }
}

