                "INSERT INTO accounts (userid, user_pass, sex) VALUES (?, ?, ?)",
                &[&"user1" as &dyn rusqlite::types::ToSql, &"hash", &"M"],
            )?;
            Err(crate::error::Error::DatabaseBackend("intentional".into()))
        });
